window.EC_CORE = {"data/class/SC_Fpdf.php":"<?php\n/*\n * This file is part of EC-CUBE\n *\n * Copyright(c) EC-CUBE CO.,LTD. All Rights Reserved.\n *\n * http://www.ec-cube.co.jp/\n *\n * This program is free software; you can redistribute it and/or\n * modify it under the terms of the GNU General Public License\n * as published by the Free Software Foundation; either version 2\n * of the License, or (at your option) any later version.\n *\n * This program is distributed in the hope that it will be useful,\n * but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n * You should have received a copy of the GNU General Public License\n * along with this program; if not, write to the Free Software\n * Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n */\n\n/*\n * PDF 納品書を出力する\n *\n * TODO ページクラスとすべき要素を多々含んでいるように感じる。\n */\n\ndefine('PDF_TEMPLATE_REALDIR', TEMPLATE_ADMIN_REALDIR.'pdf/');\n\nclass SC_Fpdf extends SC_Helper_FPDI\n{\n    /** @var string */\n    public $tpl_pdf;\n    /** @var int */\n    public $pdf_download;\n    /** @var string */\n    public $tpl_title;\n    /** @var string */\n    public $tpl_dispmode;\n    /** @var array */\n    public $arrPref;\n    /** @var array */\n    public $width_cell;\n    /** @var array */\n    public $label_cell;\n    /** @var array */\n    public $arrMessage;\n    /** @var array */\n    public $arrData;\n    /** @var array */\n    public $arrDisp;\n    /** @var bool */\n    public $disp_mode;\n    /** @var int */\n    public $pageno;\n\n    public function __construct($download, $title, $tpl_pdf = 'nouhinsyo1.pdf')\n    {\n        parent::__construct();\n\n        // デフォルトの設定\n        $this->tpl_pdf = PDF_TEMPLATE_REALDIR.$tpl_pdf;  // テンプレートファイル\n        $this->pdf_download = $download;      // PDFのダウンロード形式（0:表示、1:ダウンロード）\n        $this->tpl_title = $title;\n        $this->tpl_dispmode = 'real';      // 表示モード\n        $masterData = new SC_DB_MasterData_Ex();\n        $this->arrPref = $masterData->getMasterData('mtb_pref');\n        $this->width_cell = [110.3, 12, 21.7, 24.5];\n\n        $this->label_cell[] = '商品名 / 商品コード / [ 規格 ]';\n        $this->label_cell[] = '数量';\n        $this->label_cell[] = '単価';\n        $this->label_cell[] = '金額(税込)';\n\n        $this->arrMessage = [\n            'このたびはお買上げいただきありがとうございます。',\n            '下記の内容にて納品させていただきます。',\n            'ご確認くださいますよう、お願いいたします。',\n        ];\n\n        // SJISフォント\n        $this->AddSJISFont();\n        $this->SetFont('SJIS');\n\n        // ページ総数取得\n        $this->AliasNbPages();\n\n        // マージン設定\n        $this->SetMargins(15, 20);\n\n        // PDFを読み込んでページ数を取得\n        $this->pageno = $this->setSourceFile($this->tpl_pdf);\n    }\n\n    public function setData($arrData)\n    {\n        $this->arrData = $arrData;\n\n        // ページ番号よりIDを取得\n        $tplidx = $this->ImportPage(1);\n\n        // ページを追加（新規）\n        $this->AddPage();\n\n        // 表示倍率(100%)\n        $this->SetDisplayMode($this->tpl_dispmode);\n\n        if (SC_Utils_Ex::sfIsInt($arrData['order_id'])) {\n            $this->disp_mode = true;\n        }\n\n        // テンプレート内容の位置、幅を調整 ※useTemplateに引数を与えなければ100%表示がデフォルト\n        $this->useTemplate($tplidx);\n\n        $this->setShopData();\n        $this->setMessageData();\n        $this->setOrderData();\n        $this->setEtcData();\n    }\n\n    private function setShopData()\n    {\n        // ショップ情報\n\n        $objDb = new SC_Helper_DB_Ex();\n        $arrInfo = $objDb->sfGetBasisData();\n\n        // ショップ名\n        $this->lfText(125, 60, $arrInfo['shop_name'], 8, 'B');\n        // URL\n        $this->lfText(125, 63, $arrInfo['law_url'], 8);\n        // 会社名\n        $this->lfText(125, 68, $arrInfo['law_company'], 8);\n        // 郵便番号\n        $text = '〒 '.$arrInfo['law_zip01'].' - '.$arrInfo['law_zip02'];\n        $this->lfText(125, 71, $text, 8);\n        // 都道府県+所在地\n        $text = $this->arrPref[$arrInfo['law_pref']].$arrInfo['law_addr01'];\n        $this->lfText(125, 74, $text, 8);\n        $this->lfText(125, 77, $arrInfo['law_addr02'], 8);\n\n        $text = 'TEL: '.$arrInfo['law_tel01'].'-'.$arrInfo['law_tel02'].'-'.$arrInfo['law_tel03'];\n        // FAX番号が存在する場合、表示する\n        if (strlen($arrInfo['law_fax01']) > 0) {\n            $text .= '　FAX: '.$arrInfo['law_fax01'].'-'.$arrInfo['law_fax02'].'-'.$arrInfo['law_fax03'];\n        }\n        $this->lfText(125, 80, $text, 8);  // TEL・FAX\n\n        if (strlen($arrInfo['law_email']) > 0) {\n            $text = 'Email: '.$arrInfo['law_email'];\n            $this->lfText(125, 83, $text, 8);      // Email\n        }\n\n        // ロゴ画像\n        $logo_file = PDF_TEMPLATE_REALDIR.'logo.png';\n        $this->Image($logo_file, 124, 46, 40);\n\n        if (defined('INVOICE_REGISTRATION_NUM')) {\n            $text = '登録番号: '.INVOICE_REGISTRATION_NUM;\n            $this->lfText(125, 87, $text, 8);\n        }\n    }\n\n    private function setMessageData()\n    {\n        // メッセージ\n        $this->lfText(27, 89, $this->arrData['msg1'], 8);  // メッセージ1\n        $this->lfText(27, 92, $this->arrData['msg2'], 8);  // メッセージ2\n        $this->lfText(27, 95, $this->arrData['msg3'], 8);  // メッセージ3\n        $text = '作成日: '.$this->arrData['year'].'年'.$this->arrData['month'].'月'.$this->arrData['day'].'日';\n        $this->lfText(158, 288, $text, 8);  // 作成日\n    }\n\n    private function setOrderData()\n    {\n        $arrOrder = [];\n        // DBから受注情報を読み込む\n        $this->lfGetOrderData($this->arrData['order_id']);\n\n        // 購入者情報\n        $text = '〒 '.$this->arrDisp['order_zip01'].' - '.$this->arrDisp['order_zip02'];\n        $this->lfText(23, 43, $text, 8); // 購入者郵便番号\n\n        $y = 47; // 住所1の1行目の高さ\n\n        $text = $this->arrPref[$this->arrDisp['order_pref']].$this->arrDisp['order_addr01']; // 購入者都道府県+住所1\n\n        while (mb_strwidth($text) > 68) {\n            $line = mb_strimwidth($text, 0, 68); // 1行分の文字列\n            $this->lfText(27, $y, $line, 8);\n            $cut = strlen($line);\n            $text = substr($text, $cut, strlen($text) - $cut);\n            $y += 3;\n        }\n        if ($text != '') {\n            $this->lfText(27, $y, $text, 8);\n            $y += 3;\n        }\n\n        $text = $this->arrDisp['order_addr02']; // 購入者住所2\n\n        while (mb_strwidth($text) > 68) {\n            $line = mb_strimwidth($text, 0, 68); // 1行分の文字列\n            $this->lfText(27, $y, $line, 8);\n            $cut = strlen($line);\n            $text = substr($text, $cut, strlen($text) - $cut);\n            $y += 3;\n        }\n        if ($text != '') {\n            $this->lfText(27, $y, $text, 8);\n            $y += 3;\n        }\n\n        $text = SC_Utils_Ex::formatName($this->arrDisp, 'order_name').' 様';\n        $this->lfText(27, $y + 2, $text, 11); // 購入者氏名\n\n        // お届け先情報\n        $this->SetFont('SJIS', '', 10);\n        $this->lfText(25, 125, SC_Utils_Ex::sfDispDBDate($this->arrDisp['create_date']), 10); // ご注文日\n        $this->lfText(25, 135, $this->arrDisp['order_id'], 10); // 注文番号\n\n        $this->SetFont('Gothic', 'B', 15);\n        $this->Cell(0, 10, $this->tpl_title, 0, 2, 'C', 0, '');  // 文書タイトル（納品書・請求書）\n        $this->Cell(0, 66, '', 0, 2, 'R', 0, '');\n        $this->Cell(5, 0, '', 0, 0, 'R', 0, '');\n        $this->SetFont('SJIS', 'B', 15);\n        $this->Cell(67, 8, number_format($this->arrDisp['payment_total']).' 円', 0, 2, 'R', 0, '');\n        $this->Cell(0, 45, '', 0, 2, '', 0, '');\n\n        $this->SetFont('SJIS', '', 8);\n\n        $monetary_unit = '円';\n        $point_unit = 'Pt';\n\n        $arrTaxableTotal = [];\n        $defaultTaxRule = SC_Helper_TaxRule_Ex::getTaxRule();\n        $i = 0;\n        // 受注明細情報\n        if (isset($this->arrDisp['quantity']) && is_array($this->arrDisp['quantity'])) {\n            for (; $i < count($this->arrDisp['quantity']); $i++) {\n                // 購入数量\n                $data[0] = $this->arrDisp['quantity'][$i];\n\n                // 税込金額（単価）\n                $data[1] = $this->arrDisp['price'][$i] + SC_Helper_TaxRule_Ex::calcTax($this->arrDisp['price'][$i], $this->arrDisp['tax_rate'][$i], $this->arrDisp['tax_rule'][$i]);\n\n                // 小計（商品毎）\n                $data[2] = $data[0] * $data[1];\n\n                $arrOrder[$i][0] = $this->arrDisp['product_name'][$i].' / ';\n                $arrOrder[$i][0] .= $this->arrDisp['product_code'][$i].' / ';\n                if ($this->arrDisp['classcategory_name1'][$i]) {\n                    $arrOrder[$i][0] .= ' [ '.$this->arrDisp['classcategory_name1'][$i];\n                    if ($this->arrDisp['classcategory_name2'][$i] == '') {\n                        $arrOrder[$i][0] .= ' ]';\n                    } else {\n                        $arrOrder[$i][0] .= ' * '.$this->arrDisp['classcategory_name2'][$i].' ]';\n                    }\n                }\n\n                // 標準税率より低い税率は軽減税率として※を付与\n                if ($this->arrDisp['tax_rate'][$i] < $defaultTaxRule['tax_rate']) {\n                    $arrOrder[$i][0] .= ' ※';\n                }\n                $arrOrder[$i][1] = number_format($data[0]);\n                $arrOrder[$i][2] = number_format($data[1]).$monetary_unit;\n                $arrOrder[$i][3] = number_format($data[2]).$monetary_unit;\n                if (array_key_exists($this->arrDisp['tax_rate'][$i], $arrTaxableTotal) === false) {\n                    $arrTaxableTotal[$this->arrDisp['tax_rate'][$i]] = 0;\n                }\n                $arrTaxableTotal[$this->arrDisp['tax_rate'][$i]] += $data[2];\n            }\n        }\n\n        $arrOrder[$i][0] = '';\n        $arrOrder[$i][1] = '';\n        $arrOrder[$i][2] = '';\n        $arrOrder[$i][3] = '';\n\n        $i++;\n        $arrOrder[$i][0] = '';\n        $arrOrder[$i][1] = '';\n        $arrOrder[$i][2] = '商品合計';\n        $arrOrder[$i][3] = number_format($this->arrDisp['subtotal']).$monetary_unit;\n\n        $i++;\n        $arrOrder[$i][0] = '';\n        $arrOrder[$i][1] = '';\n        $arrOrder[$i][2] = '送料';\n        $arrOrder[$i][3] = number_format($this->arrDisp['deliv_fee']).$monetary_unit;\n        $arrTaxableTotal[(int) $defaultTaxRule['tax_rate']] += $this->arrDisp['deliv_fee'];\n\n        $i++;\n        $arrOrder[$i][0] = '';\n        $arrOrder[$i][1] = '';\n        $arrOrder[$i][2] = '手数料';\n        $arrOrder[$i][3] = number_format($this->arrDisp['charge']).$monetary_unit;\n        $arrTaxableTotal[(int) $defaultTaxRule['tax_rate']] += $this->arrDisp['charge'];\n\n        $i++;\n        $arrOrder[$i][0] = '';\n        $arrOrder[$i][1] = '';\n        $arrOrder[$i][2] = '値引き';\n        $discount_total = ($this->arrDisp['use_point'] * POINT_VALUE) + $this->arrDisp['discount'];\n        $arrOrder[$i][3] = '- '.number_format($discount_total).$monetary_unit;\n\n        $i++;\n        $arrOrder[$i][0] = '';\n        $arrOrder[$i][1] = '';\n        $arrOrder[$i][2] = '請求金額';\n        $arrOrder[$i][3] = number_format($this->arrDisp['payment_total']).$monetary_unit;\n\n        // ポイント表記\n        if ($this->arrData['disp_point'] && $this->arrDisp['customer_id']) {\n            $i++;\n            $arrOrder[$i][0] = '';\n            $arrOrder[$i][1] = '';\n            $arrOrder[$i][2] = '';\n            $arrOrder[$i][3] = '';\n\n            $i++;\n            $arrOrder[$i][0] = '';\n            $arrOrder[$i][1] = '';\n            $arrOrder[$i][2] = '利用ポイント';\n            $arrOrder[$i][3] = number_format($this->arrDisp['use_point']).$point_unit;\n\n            $i++;\n            $arrOrder[$i][0] = '';\n            $arrOrder[$i][1] = '';\n            $arrOrder[$i][2] = '加算ポイント';\n            $arrOrder[$i][3] = number_format($this->arrDisp['add_point']).$point_unit;\n        }\n\n        $this->FancyTable($this->label_cell, $arrOrder, $this->width_cell);\n\n        $this->SetLineWidth(.3);\n        $this->SetFont('SJIS', '', 6);\n\n        $this->Cell(0, 0, '', 0, 1, 'C', 0, '');\n        // 行頭近くの場合、表示崩れがあるためもう一個字下げする\n        if (270 <= $this->GetY()) {\n            $this->Cell(0, 0, '', 0, 1, 'C', 0, '');\n        }\n        $width = array_reduce($this->width_cell, function ($n, $w) {\n            return $n + $w;\n        });\n        $this->SetX(20);\n\n        $message = SC_Helper_TaxRule_Ex::getTaxDetail($arrTaxableTotal, $discount_total);\n        $this->MultiCell($width, 4, $message, 0, 'R', '');\n    }\n\n    /**\n     * 備考の出力を行う\n     *\n     * @return void\n     */\n    private function setEtcData()\n    {\n        $this->Cell(0, 10, '', 0, 1, 'C', 0, '');\n        $this->SetFont('Gothic', 'B', 9);\n        $this->MultiCell(0, 6, '＜ 備考 ＞', 'T', 2, 'L');\n        $this->SetFont('SJIS', '', 8);\n        $text = SC_Utils_Ex::rtrim($this->arrData['etc1'].\"\\n\".$this->arrData['etc2'].\"\\n\".$this->arrData['etc3']);\n        $this->MultiCell(0, 4, $text, '', 2, 'L');\n    }\n\n    public function createPdf()\n    {\n        // PDFをブラウザに送信\n        ob_clean();\n        if ($this->pdf_download == 1) {\n            if ($this->PageNo() == 1) {\n                $filename = 'nouhinsyo-No'.$this->arrData['order_id'].'.pdf';\n            } else {\n                $filename = 'nouhinsyo.pdf';\n            }\n            $this->Output($this->lfConvSjis($filename), 'D');\n        } else {\n            $this->Output();\n        }\n\n        // 入力してPDFファイルを閉じる\n        $this->Close();\n    }\n\n    // PDF_Japanese::Text へのパーサー\n\n    /**\n     * @param int $x\n     * @param int $y\n     */\n    private function lfText($x, $y, $text, $size = 0, $style = '')\n    {\n        // 退避\n        $bak_font_style = $this->FontStyle;\n        $bak_font_size = $this->FontSizePt;\n\n        $this->SetFont('', $style, $size);\n        $this->Text($x, $y, $text);\n\n        // 復元\n        $this->SetFont('', $bak_font_style, $bak_font_size);\n    }\n\n    // 受注データの取得\n    private function lfGetOrderData($order_id)\n    {\n        if (SC_Utils_Ex::sfIsInt($order_id)) {\n            // DBから受注情報を読み込む\n            $objPurchase = new SC_Helper_Purchase_Ex();\n            $this->arrDisp = $objPurchase->getOrder($order_id);\n            [$point] = SC_Helper_Customer_Ex::sfGetCustomerPoint($order_id, $this->arrDisp['use_point'], $this->arrDisp['add_point']);\n            $this->arrDisp['point'] = $point;\n\n            // 受注詳細データの取得\n            $arrRet = $objPurchase->getOrderDetail($order_id);\n            $arrRet = SC_Utils_Ex::sfSwapArray($arrRet);\n            $this->arrDisp = array_merge($this->arrDisp, $arrRet);\n\n            // その他支払い情報を表示\n            if ($this->arrDisp['memo02'] != '') {\n                $this->arrDisp['payment_info'] = unserialize($this->arrDisp['memo02']);\n            }\n            $this->arrDisp['payment_type'] = 'お支払い';\n        }\n    }\n}\n","data/class/pages/admin/order/LC_Page_Admin_Order_Pdf.php":"<?php\n/*\n * This file is part of EC-CUBE\n *\n * Copyright(c) EC-CUBE CO.,LTD. All Rights Reserved.\n *\n * http://www.ec-cube.co.jp/\n *\n * This program is free software; you can redistribute it and/or\n * modify it under the terms of the GNU General Public License\n * as published by the Free Software Foundation; either version 2\n * of the License, or (at your option) any later version.\n *\n * This program is distributed in the hope that it will be useful,\n * but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n * You should have received a copy of the GNU General Public License\n * along with this program; if not, write to the Free Software\n * Foundation, Inc., 59 Temple Place - Suite 330, Boston, MA  02111-1307, USA.\n */\n\n/**\n * 帳票出力 のページクラス.\n *\n * @author EC-CUBE CO.,LTD.\n *\n * @version $Id$\n */\nclass LC_Page_Admin_Order_Pdf extends LC_Page_Admin_Ex\n{\n    /** @var array */\n    public $SHORTTEXT_MAX;\n    /** @var array */\n    public $MIDDLETEXT_MAX;\n    /** @var array */\n    public $LONGTEXT_MAX;\n    /** @var array */\n    public $arrType;\n    /** @var array */\n    public $arrDownload;\n\n    /**\n     * Page を初期化する.\n     *\n     * @return void\n     */\n    public function init()\n    {\n        parent::init();\n        $this->tpl_mainpage = 'order/pdf_input.tpl';\n        $this->tpl_mainno = 'order';\n        $this->tpl_subno = 'pdf';\n        $this->tpl_maintitle = '受注管理';\n        $this->tpl_subtitle = '帳票出力';\n\n        $this->SHORTTEXT_MAX = STEXT_LEN;\n        $this->MIDDLETEXT_MAX = MTEXT_LEN;\n        $this->LONGTEXT_MAX = LTEXT_LEN;\n\n        $this->arrType[0] = '納品書';\n\n        $this->arrDownload[0] = 'ブラウザに開く';\n        $this->arrDownload[1] = 'ファイルに保存';\n    }\n\n    /**\n     * Page のプロセス.\n     *\n     * @return void\n     */\n    public function process()\n    {\n        $this->action();\n        $this->sendResponse();\n    }\n\n    /**\n     * Page のアクション.\n     *\n     * @return void\n     */\n    public function action()\n    {\n        $objDb = new SC_Helper_DB_Ex();\n        $objDate = new SC_Date_Ex(1901);\n        $objDate->setStartYear(RELEASE_YEAR);\n        $this->arrYear = $objDate->getYear();\n        $this->arrMonth = $objDate->getMonth();\n        $this->arrDay = $objDate->getDay();\n\n        // パラメーター管理クラス\n        $this->objFormParam = new SC_FormParam_Ex();\n        // パラメーター情報の初期化\n        $this->lfInitParam($this->objFormParam);\n        $this->objFormParam->setParam($_POST);\n        // 入力値の変換\n        $this->objFormParam->convParam();\n\n        switch ($this->getMode()) {\n            case 'confirm':\n                $status = $this->createPdf($this->objFormParam);\n                if ($status === true) {\n                    SC_Response_Ex::actionExit();\n                } else {\n                    $this->arrErr = $status;\n                }\n                break;\n            default:\n                $this->arrForm = $this->createFromValues($_GET['order_id'] ?? null, $_POST['pdf_order_id'] ?? null);\n                break;\n        }\n        $this->setTemplate($this->tpl_mainpage);\n    }\n\n    /**\n     * PDF作成フォームのデフォルト値の生成\n     */\n    public function createFromValues($order_id, $pdf_order_id)\n    {\n        // ここが$arrFormの初登場ということを明示するため宣言する。\n        $arrForm = [];\n        // タイトルをセット\n        $arrForm['title'] = 'お買上げ明細書(納品書)';\n\n        // 今日の日付をセット\n        $arrForm['year'] = date('Y');\n        $arrForm['month'] = date('n');\n        $arrForm['day'] = date('j');\n\n        // メッセージ\n        $arrForm['msg1'] = 'このたびはお買上げいただきありがとうございます。';\n        $arrForm['msg2'] = '下記の内容にて納品させていただきます。';\n        $arrForm['msg3'] = 'ご確認くださいますよう、お願いいたします。';\n\n        // 注文番号があったら、セットする\n        if (SC_Utils_Ex::sfIsInt($order_id)) {\n            $arrForm['order_id'][0] = $order_id;\n        } elseif (is_array($pdf_order_id)) {\n            sort($pdf_order_id);\n            foreach ($pdf_order_id as $key => $val) {\n                $arrForm['order_id'][] = $val;\n            }\n        }\n\n        return $arrForm;\n    }\n\n    /**\n     * PDFの作成\n     *\n     * @param SC_FormParam $objFormParam\n     */\n    public function createPdf(&$objFormParam)\n    {\n        $arrErr = $this->lfCheckError($objFormParam);\n        $arrRet = $objFormParam->getHashArray();\n\n        // タイトルが入力されていなければ、デフォルトのタイトルを表示\n        if ($arrRet['title'] == '') {\n            $arrRet['title'] = 'お買上げ明細書(納品書)';\n        }\n\n        $this->arrForm = $arrRet;\n        // エラー入力なし\n        if (count($arrErr) == 0) {\n            $objFpdf = new SC_Fpdf_Ex($arrRet['download'], $arrRet['title']);\n            foreach ($arrRet['order_id'] as $key => $val) {\n                $arrPdfData = $arrRet;\n                $arrPdfData['order_id'] = $val;\n                $objFpdf->setData($arrPdfData);\n            }\n            $objFpdf->createPdf();\n\n            return true;\n        } else {\n            return $arrErr;\n        }\n    }\n\n    /**\n     *  パラメーター情報の初期化\n     *\n     *  @param SC_FormParam\n     * @param SC_FormParam_Ex $objFormParam\n     */\n    public function lfInitParam(&$objFormParam)\n    {\n        $objFormParam->addParam('注文番号', 'order_id', INT_LEN, 'n', ['EXIST_CHECK', 'MAX_LENGTH_CHECK', 'NUM_CHECK']);\n        $objFormParam->addParam('注文番号', 'pdf_order_id', INT_LEN, 'n', ['MAX_LENGTH_CHECK', 'NUM_CHECK']);\n        $objFormParam->addParam('発行日', 'year', INT_LEN, 'n', ['EXIST_CHECK', 'MAX_LENGTH_CHECK', 'NUM_CHECK']);\n        $objFormParam->addParam('発行日', 'month', INT_LEN, 'n', ['EXIST_CHECK', 'MAX_LENGTH_CHECK', 'NUM_CHECK']);\n        $objFormParam->addParam('発行日', 'day', INT_LEN, 'n', ['EXIST_CHECK', 'MAX_LENGTH_CHECK', 'NUM_CHECK']);\n        $objFormParam->addParam('帳票の種類', 'type', INT_LEN, 'n', ['EXIST_CHECK', 'MAX_LENGTH_CHECK', 'NUM_CHECK']);\n        $objFormParam->addParam('ダウンロード方法', 'download', INT_LEN, 'n', ['EXIST_CHECK', 'MAX_LENGTH_CHECK', 'NUM_CHECK']);\n        $objFormParam->addParam('帳票タイトル', 'title', STEXT_LEN, 'KVa', ['MAX_LENGTH_CHECK']);\n        $objFormParam->addParam('帳票メッセージ1行目', 'msg1', STEXT_LEN * 3 / 5, 'KVa', ['MAX_LENGTH_CHECK']);\n        $objFormParam->addParam('帳票メッセージ2行目', 'msg2', STEXT_LEN * 3 / 5, 'KVa', ['MAX_LENGTH_CHECK']);\n        $objFormParam->addParam('帳票メッセージ3行目', 'msg3', STEXT_LEN * 3 / 5, 'KVa', ['MAX_LENGTH_CHECK']);\n        $objFormParam->addParam('備考1行目', 'etc1', STEXT_LEN, 'KVa', ['MAX_LENGTH_CHECK']);\n        $objFormParam->addParam('備考2行目', 'etc2', STEXT_LEN, 'KVa', ['MAX_LENGTH_CHECK']);\n        $objFormParam->addParam('備考3行目', 'etc3', STEXT_LEN, 'KVa', ['MAX_LENGTH_CHECK']);\n        $objFormParam->addParam('ポイント表記', 'disp_point', INT_LEN, 'n', ['EXIST_CHECK', 'MAX_LENGTH_CHECK']);\n    }\n\n    /**\n     *  入力内容のチェック\n     *\n     *  @var SC_FormParam\n     *\n     * @param SC_FormParam $objFormParam\n     */\n    public function lfCheckError(&$objFormParam)\n    {\n        // 入力データを渡す。\n        $arrParams = $objFormParam->getHashArray();\n        $arrErr = $objFormParam->checkError();\n        $objError = new SC_CheckError_Ex($arrParams);\n\n        $year = $objFormParam->getValue('year');\n        $month = $objFormParam->getValue('month');\n        $day = $objFormParam->getValue('day');\n\n        $objError->doFunc(['発行日', 'year', 'month', 'day'], ['CHECK_DATE']);\n        $arrErr = array_merge($arrErr, $objError->arrErr);\n\n        $objQuery = SC_Query_Ex::getSingletonInstance();\n\n        $order_temp = $_POST['order_id'];\n        $order_max = max($order_temp);\n\n        $date_check = $objQuery->select('create_date', 'dtb_order', 'order_id = ?', [$order_max]);\n\n        $date_check = substr($date_check[0]['create_date'], 0, 10);\n        $date_check = explode('-', $date_check);\n        $order_year = $date_check[0];\n        $order_month = $date_check[1];\n        $order_day = $date_check[2];\n\n        $date1 = sprintf('%d%02d%02d000000', $order_year, $order_month, $order_day);\n        $date2 = sprintf('%d%02d%02d235959', $year, $month, $day);\n\n        if ($date1 > $date2) {\n            $arrErr['year'] = '※ 発行日は受注日以降の日付を入力してください。<br />';\n        }\n\n        return $arrErr;\n    }\n}\n","data/class_extends/README.md":"# 拡張カスタマイズ用クラス用ディレクトリ\n\n本ディレクトリ以下に `<クラス名>_Ex.php` を作成することにより、 [data/class](../class/) 以下のクラスを拡張カスタマイズできます。\n\n## 使用方法\n\n### SC_Product クラスをカスタマイズする場合\n\n以下の内容で、 SC_Product_Ex.php を作成します。\n\n```php\n<?php\n// path/to/ec-cube2/data/class_extends/SC_Product_Ex.php\nclass SC_Product_Ex extends SC_Product\n{\n    public function customizeMethod()\n    {\n        // ....\n    }\n}\n```\n\n## `*_Ex.php` の配置場所\n\n`*_Ex.php` は、元クラスの [data/class](../class/) からの相対ディレクトリに合わせて配置します。\n先頭のディレクトリ名には `_extends` を付けます (`pages` のみ `page_extends` になります)。\n\n| 元クラス | `*_Ex.php` の配置場所 |\n|---|---|\n| `data/class/SC_Product.php` | `data/class_extends/SC_Product_Ex.php` |\n| `data/class/helper/SC_Helper_Purchase.php` | `data/class_extends/helper_extends/SC_Helper_Purchase_Ex.php` |\n| `data/class/pages/mypage/LC_Page_AbstractMypage.php` | `data/class_extends/page_extends/mypage/LC_Page_AbstractMypage_Ex.php` |\n| `data/class/pages/admin/order/LC_Page_Admin_Order_Edit.php` | `data/class_extends/page_extends/admin/order/LC_Page_Admin_Order_Edit_Ex.php` |\n\n`*_Ex.php` が存在しない場合、 `*_Ex` クラスは元クラスのエイリアスになります。\n\n## 作成済みの `*_Ex.php` ファイル\n\nEC-CUBE2.17.2 までは、 [data/class](../class/) 以下すべてのクラスの拡張カスタマイズ用クラスが作成されていました。\n[カスタマイズ時の利便性向上のため](https://github.com/EC-CUBE/ec-cube2/pull/526)、これらのファイルは削除されましたが、以下のファイルは下位互換性維持のため削除せずに残してあります。\n\n### [app_initial.php](../app_initial.php) の spl_autoload_register を登録する前に必要なクラス\n\n- [data/class_extends/SC_ClassAutoloader_Ex.php](SC_ClassAutoloader_Ex.php)\n- [data/class_extends/helper_extends/SC_Helper_Plugin_Ex.php](helper_extends/SC_Helper_Plugin_Ex.php)\n- [data/class_extends/SC_Query_Ex.php](SC_Query_Ex.php)\n\n### 決済モジュールやプラグイン、 user_data 以下の PHP で `require` されているクラス\n\n- [data/class_extends/page_extends/mypage/LC_Page_AbstractMypage_Ex.php](page_extends/mypage/LC_Page_AbstractMypage_Ex.php)\n- [data/class_extends/page_extends/LC_Page_Ex.php](page_extends/LC_Page_Ex.php)\n- [data/class_extends/page_extends/admin/LC_Page_Admin_Ex.php](page_extends/admin/LC_Page_Admin_Ex.php)\n- [data/class_extends/page_extends/shopping/LC_Page_Shopping_Payment_Ex.php](page_extends/shopping/LC_Page_Shopping_Payment_Ex.php)\n- [data/class_extends/page_extends/shopping/LC_Page_Shopping_LoadPaymentModule_Ex.php](page_extends/shopping/LC_Page_Shopping_LoadPaymentModule_Ex.php)\n- [data/class_extends/SC_Display_Ex.php](SC_Display_Ex.php)\n- [data/class_extends/SC_Response_Ex.php](SC_Response_Ex.php)\n- [data/class_extends/page_extends/cart/LC_Page_Cart_Ex.php](LC_Page_Cart_Ex.php)\n- [data/class_extends/SC_FormParam_Ex.php](SC_FormParam_Ex.php)\n- [data/class_extends/page_extends/admin/ownersstore/LC_Page_Admin_OwnersStore_Ex.php](LC_Page_Admin_OwnersStore_Ex.php)\n- [data/class_extends/plugin_extends/SC_Plugin_Util_Ex.php](SC_Plugin_Util_Ex.php)\n- [data/class_extends/page_extends/admin/order/LC_Page_Admin_Order_Edit_Ex.php](LC_Page_Admin_Order_Edit_Ex.php)\n"};
